with open(sys.argv[1], 'w') as f:
    f.write('static const struct { unsigned nid; const char *name; } psp_names[] = {\n')
    for n in NAMES:
        f.write('    {0x%08Xu, "%s"},\n' % (struct.unpack('<I', hashlib.sha1(n.encode()).digest()[:4])[0], n))
    f.write('};\n')
